'use strict';

import {
  createError,
  REV_CONFLICT,
  MISSING_DOC,
  MISSING_STUB,
  INVALID_REV
} from 'pouchdb-errors';

import preProcessAttachment from './attachments';
import { META_LOCAL_STORE, idbError } from './util';

// Local documents (ids starting with `_local/`) carry 0-N revisions and keep
// no history; see the PouchDB guide and CouchDB's _local API. Earlier releases
// of this adapter let local documents fall through to the ordinary revision
// path and stored 1-<hash> revisions instead, so a database written by one of
// those releases can hold legacy local revisions. Carry the generation over in
// that case so the first update after upgrading still moves forward.
function nextLocalRev(oldRev) {
  if (!oldRev) {
    return '0-1';
  }
  const localRev = /^0-(\d+)$/.exec(oldRev);
  if (localRev) {
    return '0-' + (parseInt(localRev[1], 10) + 1);
  }
  const legacyRev = /^(\d+)-/.exec(oldRev);
  return '0-' + (legacyRev ? parseInt(legacyRev[1], 10) + 1 : 1);
}

// Convert the attachments of raw local documents (as supplied by the user) to
// the stored format before the IndexedDB transaction is opened, because the
// digest work is asynchronous and would let the transaction commit early.
export function preProcessLocalAttachments(docs, attachmentFormat) {
  return Promise.all(docs.map(function (doc) {
    if (!doc._attachments) {
      return doc;
    }

    const attachments = Object.keys(doc._attachments).map(function (name) {
      const attachment = doc._attachments[name];
      attachment.name = name;
      return preProcessAttachment(attachment, attachmentFormat);
    });

    return Promise.all(attachments).then(function (processed) {
      const result = {};
      processed.forEach(function (attachment) {
        result[attachment.name] = attachment;
        delete attachment.name;
      });
      doc._attachments = result;
      return doc;
    });
  }));
}

function copyDocData(doc) {
  const data = {};
  for (const key in doc) {
    if (!Object.prototype.hasOwnProperty.call(doc, key)) {
      continue;
    }
    if (key === '_id' || key === '_rev' || key === '_deleted' ||
        key === '_revisions') {
      continue;
    }
    data[key] = doc[key];
  }
  return data;
}

function buildStoredAttachments(doc, oldDoc, newRev, revpos) {
  const attachments = Object.assign({}, oldDoc && oldDoc.attachments);
  const data = doc;

  if (!data._attachments) {
    return { data, attachments };
  }

  for (const name of Object.keys(data._attachments)) {
    const attachment = data._attachments[name];
    if (attachment.stub) {
      const stored = attachments[attachment.digest];
      if (!stored) {
        return { error: createError(MISSING_STUB) };
      }
      attachments[attachment.digest] = Object.assign({}, stored, {
        revs: Object.assign({}, stored.revs, { [newRev]: true })
      });
      data._attachments[name] = {
        stub: true,
        digest: attachment.digest,
        content_type: attachment.content_type,
        length: attachment.length,
        revpos: attachment.revpos
      };
    } else {
      attachments[attachment.digest] = Object.assign({}, attachment, {
        revs: { [newRev]: true }
      });
      data._attachments[name] = {
        stub: true,
        digest: attachment.digest,
        content_type: attachment.content_type,
        length: attachment.length,
        revpos
      };
    }
  }

  return { data, attachments };
}

// Write one local document. The caller owns the transaction (opts.ctx when
// called from bulkDocs, otherwise the adapter's transaction wrapper).
export function putLocal(txn, doc, opts, callback) {
  if (typeof opts === 'function') {
    callback = opts;
    opts = {};
  }

  delete doc._revisions;

  const id = doc._id;
  const oldRev = doc._rev;
  const store = txn.objectStore(META_LOCAL_STORE);

  // bulkDocs does not run local documents through parseDoc, which is what
  // would normally reject a malformed revision.
  if (oldRev && !/^\d+-[^-]*$/.test(oldRev)) {
    return callback(createError(INVALID_REV));
  }

  const getReq = store.get(id);
  getReq.onerror = idbError(callback);
  getReq.onsuccess = function (e) {
    const oldDoc = e.target.result;

    // A new document must not name a revision, and an existing one must name
    // its current revision; anything else is a conflict.
    if (oldDoc ? oldDoc.rev !== oldRev : Boolean(oldRev)) {
      return callback(createError(REV_CONFLICT));
    }

    const newRev = nextLocalRev(oldRev);
    const revNum = parseInt(newRev.split('-')[1], 10);
    const data = copyDocData(doc);
    const built = buildStoredAttachments(data, oldDoc, newRev, revNum);

    if (built.error) {
      return callback(built.error);
    }

    const stored = {
      id,
      rev: newRev,
      // 0-N is the local revision scheme: the revision number is the id and
      // the generation is 0, so the tree has a single root at position 0.
      rev_tree: [{
        pos: 0,
        ids: [String(revNum), {status: 'available'}, []]
      }],
      revs: {
        [newRev]: {data: built.data}
      },
      attachments: built.attachments,
      data: built.data,
      deleted: 0
    };

    const putReq = store.put(stored);
    putReq.onerror = idbError(callback);
    putReq.onsuccess = function () {
      callback(null, {ok: true, id, rev: newRev});
    };
  };
}

// Remove one local document, mirroring the leveldb and idb adapters: a missing
// document is a 404 and a revision mismatch is a 409.
export function removeLocal(txn, doc, opts, callback) {
  if (typeof opts === 'function') {
    callback = opts;
    opts = {};
  }

  const id = doc._id;
  const store = txn.objectStore(META_LOCAL_STORE);

  if (doc._rev && !/^\d+-[^-]*$/.test(doc._rev)) {
    return callback(createError(INVALID_REV));
  }

  const getReq = store.get(id);
  getReq.onerror = idbError(callback);
  getReq.onsuccess = function (e) {
    const oldDoc = e.target.result;

    if (!oldDoc) {
      return callback(createError(MISSING_DOC));
    }
    if (oldDoc.rev !== doc._rev) {
      return callback(createError(REV_CONFLICT));
    }

    const deleteReq = store.delete(id);
    deleteReq.onerror = idbError(callback);
    deleteReq.onsuccess = function () {
      callback(null, {ok: true, id, rev: '0-0'});
    };
  };
}
